INSERT INTO products ("id", "partner_id", "sku", "oem_code", "part_brand", "category_id", "name", "slug", "description", "short_specs", "price", "original_price", "stock", "reserved_stock", "weight_g", "width_cm", "height_cm", "depth_cm", "status", "reject_reason", "is_admin_created", "is_featured", "is_hot", "is_new", "sold_count", "view_count", "rating_avg", "rating_count", "warranty_months", "approved_by", "approved_at", "published_at", "created_at", "updated_at", "meta_title", "meta_description", "focus_keyword", "canonical_url", "og_image", "is_indexed", "price_before_tax", "tax_amount", "vat_rate", "oem_code2", "min_stock", "max_stock", "features", "specifications", "car_brand_id", "sale_price", "is_on_sale", "show_on_home", "show_on_promo", "seo_title", "seo_description", "seo_keyword", "video_url", "cost_price", "total_import_value", "location_code", "is_call_price", "is_active", "wholesale_price", "seo_secondary_keywords") VALUES (1108, 1, '10369836', '10369836', 'DENSO', 46, 'DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836 | 10369836', 'dan-lanh-dieu-hoa-o-to-zs-2020-2023-denso-10369836-10369836', 'Dàn lạnh ZS Denso 10369836 chính hãng Sản phẩm Dàn lạnh ZS (mã 10369836) của thương hiệu Denso là lựa chọn thay thế lý tưởng ZS (2020-2023). Bộ phận này trao đổi nhiệt, hấp thụ hơi nóng trong cabin và thổi ra luồng khí mát lạnh khoang nội thất. Với uy tín toàn cầu trong lĩnh vực điều hòa ô tô, Denso mang đến sản phẩm bền bỉ, vận hành êm ái và độ tin cậy cao người dùng tại Việt Nam. Ưu điểm vượt trội của Dàn lạnh ZS Denso Khác với hàng trôi nổi, dàn lạnh zs Denso mã 10369836 được sản xuất theo đúng thông số kỹ thuật nguyên bản. Điều này giúp hệ thống điều hòa của ZS hoạt động ổn định, làm mát nhanh, đồng thời giảm thiểu rủi ro hỏng hóc và chi phí bảo dưỡng về lâu dài. Chuẩn OEM Nhật Bản: chất lượng tương đương phụ tùng lắp ráp theo xe. Làm lạnh nhanh, sâu: đáp ứng tốt nhu cầu sử dụng hằng ngày và đường dài. Khả năng chống ăn mòn: bền bỉ với độ ẩm và môi trường khắc nghiệt. Hoạt động ổn định: ít hỏng vặt, giảm chi phí sửa chữa. Khớp nối chính xác: dễ dàng lắp đặt ZS. Hướng dẫn chọn mua và lắp đặt Trước khi mua, hãy kiểm tra mã 10369836 và đối chiếu với dòng ZS để chọn đúng sản phẩm. Trong quá trình lắp đặt, nên vệ sinh hệ thống, thay thế gioăng làm kín nếu cần và nạp môi chất lạnh đúng tiêu chuẩn nhằm phát huy tối đa hiệu quả của dàn lạnh zs.
<!-- stage4-seo-description:start --><section class="product-seo-details"><h2>Thông tin dàn lạnh</h2><p><strong>dàn lạnh</strong> được nhận diện theo tên sản phẩm và mã tham chiếu đang lưu trên hệ thống. Khách hàng có thể sử dụng tên hoặc mã sản phẩm để tra cứu và đối chiếu trước khi đặt hàng.</p><h3>Thông tin nhận diện sản phẩm</h3><ul><li><strong>Tên sản phẩm:</strong> DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836</li><li><strong>Mã sản phẩm:</strong> 10369836</li><li><strong>Mã OEM:</strong> 10369836</li><li><strong>Danh mục:</strong> Dàn Lạnh</li><li><strong>Thương hiệu:</strong> DENSO</li></ul><figure><img src="/uploads/products/p_6a1e3906b7554.jpg" alt="DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836 - 10369836" loading="lazy"><figcaption>DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836</figcaption></figure></section><!-- stage4-seo-description:end --> <div style="background:#f0fdf4;border:1.5px solid #22c55e;border-radius:10px;padding:16px;margin:20px 0;"> <strong style="color:#15803d;font-size:15px;display:block;margin-bottom:8px;">Cooling Systems- Chuỗi Dịch vụ & Phụ tùng Điều Hòa Ô Tô Chuyên Nghiệp.</strong> <ul style="margin:0 0 0 18px;color:#166534;font-size:13.5px;line-height:1.6;padding:0;"> <li>• Hotline & Zalo tư vấn: 0705.0705.26</li> <li>• Email hỗ trợ: hotrokhachhang@autopartsvietnam.com</li> <li>• Website chính thức: https://coolingsystems.vn</li> </ul>
</div>', '', 1500000, 1512000, 999, 0, 2000, 24, 25, 6, 'draft', '', 0, 0, 0, 0, 0, 1, 0.0, 0, 12, NULL, NULL, NULL, '2026-05-30 23:31:44', '2026-08-12 16:28:40', '', 'Dàn lạnh ZS Denso 10369836 chính hãng Sản phẩm Dàn lạnh ZS (mã 10369836) của thương hiệu Denso là lựa chọn thay thế lý tưởng ZS (2020-2023)....', 'DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836', '', 'p_6a1e3906b7554.jpg', 0, 1363636, 136364, 10, '10369836', 5, 999, '<h3>Đặc điểm nổi bật của Dàn lạnh ZS</h3> <p>Dưới đây là những đặc điểm kỹ thuật làm nên chất lượng của dàn lạnh zs Denso 10369836:</p> <ul> <li><strong>Tiêu chuẩn Nhật Bản:</strong> chất lượng đồng đều, kiểm định nghiêm ngặt.</li> <li><strong>Hiệu năng ổn định:</strong> duy trì độ lạnh đều trong suốt hành trình.</li> <li><strong>Độ bền cao:</strong> tuổi thọ dài, ít hỏng vặt theo thời gian.</li> <li><strong>Thiết kế tối ưu:</strong> giảm tiếng ồn và hao tổn công suất.</li> <li><strong>Khả năng chống ẩm tốt:</strong> phù hợp khí hậu Việt Nam.</li> <li><strong>Mã 10369836 rõ ràng:</strong> dễ tra cứu và thay thế ZS.</li> </ul>
<!-- stage4-seo-features:start --><section class="product-seo-features"><h3>Đặc điểm nhận diện</h3><ul><li><strong>Sản phẩm:</strong> DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836</li><li><strong>Mã tham chiếu:</strong> 10369836</li><li><strong>Thông tin tra cứu:</strong> dàn lạnh</li></ul></section><!-- stage4-seo-features:end -->', '<h3>Thông số kỹ thuật Dàn lạnh ZS Denso 10369836</h3> <table border="1" style="border-collapse:collapse;width:100%"><tbody> <tr><td style="width:40%"><strong>Tên sản phẩm</strong></td><td>Dàn lạnh ZS</td></tr> <tr><td><strong>Mã sản phẩm (SKU)</strong></td><td>10369836</td></tr> <tr>0369836</td></tr> <tr><td><strong>Thương hiệu</strong></td><td>Denso (Nhật Bản)</td></tr> <tr><td><strong>Hãng xe tương thích</strong></td><td> ZS</td></tr> <tr><td><strong>Đời xe</strong></td><td>2020-2023</td></tr> <tr><td><strong>Loại phụ tùng</strong></td><td>Dàn lạnh</td></tr> <tr><td><strong>Điện áp hoạt động</strong></td><td>12V</td></tr> <tr><td><strong>Môi chất lạnh tương thích</strong></td><td>R134a / R1234yf</td></tr> <tr><td><strong>Chất liệu</strong></td><td>Hợp kim nhôm & linh kiện cao cấp, chống ăn mòn</td></tr> <tr><td><strong>Tiêu chuẩn</strong></td><td>OEM – chính hãng</td></tr> <tr><td><strong>Tình trạng</strong></td><td>Mới 100%</td></tr> <tr><td><strong>Bảo hành</strong></td><td>12 tháng</td></tr> </tbody></table> <p><em>Lưu ý: Quý khách vui lòng đối chiếu mã OEM 10369836 và đời xe ZS để đảm bảo chọn đúng phụ tùng tương thích.</em></p>
<!-- stage4-seo-specifications:start --><section class="product-seo-specifications"><h3>Thông số tra cứu</h3><table><tbody><tr><th scope="row">Tên sản phẩm</th><td>DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836</td></tr><tr><th scope="row">Mã sản phẩm</th><td>10369836</td></tr><tr><th scope="row">Mã OEM</th><td>10369836</td></tr><tr><th scope="row">Danh mục</th><td>Dàn Lạnh</td></tr><tr><th scope="row">Thương hiệu</th><td>DENSO</td></tr></tbody></table></section><!-- stage4-seo-specifications:end -->', 19, 0, 0, 0, 0, 'DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836 | 10369836', 'Dàn lạnh ZS Denso 10369836 chính hãng Sản phẩm Dàn lạnh ZS (mã 10369836) của thương hiệu Denso là lựa chọn thay thế lý tưởng ZS (2020-2023)....', 'DÀN LẠNH điều hòa ô tô ZS 2020-2023 Denso 10369836', '', 0, 0, NULL, 0, 1, 0, 'dàn lạnh điều hòa, dàn lạnh điều hòa ô tô zs 2020-2023 denso 10369836, dàn lạnh điều hòa , dàn lạnh điều hòa denso, thay dàn lạnh điều hòa chính hãng, kiểm tra dàn lạnh điều hòa');
