INSERT INTO products ("id", "partner_id", "sku", "oem_code", "part_brand", "category_id", "name", "slug", "description", "short_specs", "price", "original_price", "stock", "reserved_stock", "weight_g", "width_cm", "height_cm", "depth_cm", "status", "reject_reason", "is_admin_created", "is_featured", "is_hot", "is_new", "sold_count", "view_count", "rating_avg", "rating_count", "warranty_months", "approved_by", "approved_at", "published_at", "created_at", "updated_at", "meta_title", "meta_description", "focus_keyword", "canonical_url", "og_image", "is_indexed", "price_before_tax", "tax_amount", "vat_rate", "oem_code2", "min_stock", "max_stock", "features", "specifications", "car_brand_id", "sale_price", "is_on_sale", "show_on_home", "show_on_promo", "seo_title", "seo_description", "seo_keyword", "video_url", "cost_price", "total_import_value", "location_code", "is_call_price", "is_active", "wholesale_price", "seo_secondary_keywords") VALUES (1273, 1, '97701-J9000', '97701-J9000 / 97701J9000', 'DENSO', 22, 'LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000 | 97701-J9000', 'loc-dieu-hoa-dieu-hoa-o-to-kona-2018-2022-denso-97701-j9000-97701-j9000', 'Lốc điều hòa Kona Denso 97701-J9000 chính hãng Sản phẩm Lốc điều hòa Kona (mã 97701-J9000) của thương hiệu Denso là lựa chọn thay thế lý tưởng Kona (2018-2022). Bộ phận này nén và đẩy môi chất lạnh tuần hoàn trong toàn bộ hệ thống điều hòa, quyết định trực tiếp đến khả năng làm mát của xe. Với uy tín toàn cầu trong lĩnh vực điều hòa ô tô, Denso mang đến sản phẩm bền bỉ, vận hành êm ái và độ tin cậy cao người dùng tại Việt Nam. Ưu điểm vượt trội của Lốc điều hòa Kona Denso Khác với hàng trôi nổi, lốc điều hòa kona Denso mã 97701-J9000 được sản xuất theo đúng thông số kỹ thuật nguyên bản. Điều này giúp hệ thống điều hòa của Kona hoạt động ổn định, làm mát nhanh, đồng thời giảm thiểu rủi ro hỏng hóc và chi phí bảo dưỡng về lâu dài. Chuẩn OEM Nhật Bản: chất lượng tương đương phụ tùng lắp ráp theo xe. Làm lạnh nhanh, sâu: đáp ứng tốt nhu cầu sử dụng hằng ngày và đường dài. Khả năng chống ăn mòn: bền bỉ với độ ẩm và môi trường khắc nghiệt. Hoạt động ổn định: ít hỏng vặt, giảm chi phí sửa chữa. Khớp nối chính xác: dễ dàng lắp đặt Kona. Hướng dẫn chọn mua và lắp đặt Trước khi mua, hãy kiểm tra mã 97701-J9000 và đối chiếu với dòng Kona để chọn đúng sản phẩm. Trong quá trình lắp đặt, nên vệ sinh hệ thống, thay thế gioăng làm kín nếu cần và nạp môi chất lạnh đúng tiêu chuẩn nhằm phát huy tối đa hiệu quả của lốc điều hòa kona.
<!-- stage4-seo-description:start --><section class="product-seo-details"><h2>Thông tin lốc điều hòa</h2><p><strong>lốc điều hòa</strong> được nhận diện theo tên sản phẩm và mã tham chiếu đang lưu trên hệ thống. Khách hàng có thể sử dụng tên hoặc mã sản phẩm để tra cứu và đối chiếu trước khi đặt hàng.</p><h3>Thông tin nhận diện sản phẩm</h3><ul><li><strong>Tên sản phẩm:</strong> LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000</li><li><strong>Mã sản phẩm:</strong> 97701-J9000</li><li><strong>Mã OEM:</strong> 97701-J9000</li><li><strong>Danh mục:</strong> Lốc Điều Hòa</li><li><strong>Thương hiệu:</strong> DENSO</li></ul><figure><img src="/uploads/products/p_6a1e39c37ebdc.jpg" alt="LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000 - 97701-J9000" loading="lazy"><figcaption>LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000</figcaption></figure></section><!-- stage4-seo-description:end --> <div style="background:#f0fdf4;border:1.5px solid #22c55e;border-radius:10px;padding:16px;margin:20px 0;"> <strong style="color:#15803d;font-size:15px;display:block;margin-bottom:8px;">Cooling Systems- Chuỗi Dịch vụ & Phụ tùng Điều Hòa Ô Tô Chuyên Nghiệp.</strong> <ul style="margin:0 0 0 18px;color:#166534;font-size:13.5px;line-height:1.6;padding:0;"> <li>• Hotline & Zalo tư vấn: 0705.0705.26</li> <li>• Email hỗ trợ: hotrokhachhang@autopartsvietnam.com</li> <li>• Website chính thức: https://coolingsystems.vn</li> </ul>
</div>', '', 10000000, 10030000, 999, 0, 6000, 20, 15, 15, 'draft', '', 0, 0, 0, 0, 0, 1, 0.0, 0, 12, NULL, NULL, NULL, '2026-05-30 23:31:44', '2026-08-12 16:28:40', '', 'Lốc điều hòa Kona Denso 97701-J9000 chính hãng Sản phẩm Lốc điều hòa Kona (mã 97701-J9000) của thương hiệu Denso là lựa chọn thay thế lý...', 'LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000', '', 'p_6a1e39c37ebdc.jpg', 0, 9090909, 909091, 10, '97701J9000', 5, 999, '<h3>Đặc điểm nổi bật của Lốc điều hòa Kona</h3> <p>Dưới đây là những đặc điểm kỹ thuật làm nên chất lượng của lốc điều hòa kona Denso 97701-J9000:</p> <ul> <li><strong>Tiêu chuẩn Nhật Bản:</strong> chất lượng đồng đều, kiểm định nghiêm ngặt.</li> <li><strong>Hiệu năng ổn định:</strong> duy trì độ lạnh đều trong suốt hành trình.</li> <li><strong>Độ bền cao:</strong> tuổi thọ dài, ít hỏng vặt theo thời gian.</li> <li><strong>Thiết kế tối ưu:</strong> giảm tiếng ồn và hao tổn công suất.</li> <li><strong>Khả năng chống ẩm tốt:</strong> phù hợp khí hậu Việt Nam.</li> <li><strong>Mã 97701-J9000 rõ ràng:</strong> dễ tra cứu và thay thế Kona.</li> </ul>
<!-- stage4-seo-features:start --><section class="product-seo-features"><h3>Đặc điểm nhận diện</h3><ul><li><strong>Sản phẩm:</strong> LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000</li><li><strong>Mã tham chiếu:</strong> 97701-J9000</li><li><strong>Thông tin tra cứu:</strong> lốc điều hòa</li></ul></section><!-- stage4-seo-features:end -->', '<h3>Thông số kỹ thuật Lốc điều hòa Kona Denso 97701-J9000</h3> <table border="1" style="border-collapse:collapse;width:100%"><tbody> <tr><td style="width:40%"><strong>Tên sản phẩm</strong></td><td>Lốc điều hòa Kona</td></tr> <tr><td><strong>Mã sản phẩm (SKU)</strong></td><td>97701-J9000</td></tr> <tr>7701-J9000 / 97701J9000</td></tr> <tr><td><strong>Thương hiệu</strong></td><td>Denso (Nhật Bản)</td></tr> <tr><td><strong>Hãng xe tương thích</strong></td><td> Kona</td></tr> <tr><td><strong>Đời xe</strong></td><td>2018-2022</td></tr> <tr><td><strong>Loại phụ tùng</strong></td><td>Lốc điều hòa</td></tr> <tr><td><strong>Điện áp hoạt động</strong></td><td>12V</td></tr> <tr><td><strong>Môi chất lạnh tương thích</strong></td><td>R134a / R1234yf</td></tr> <tr><td><strong>Chất liệu</strong></td><td>Hợp kim nhôm & linh kiện cao cấp, chống ăn mòn</td></tr> <tr><td><strong>Tiêu chuẩn</strong></td><td>OEM – chính hãng</td></tr> <tr><td><strong>Tình trạng</strong></td><td>Mới 100%</td></tr> <tr><td><strong>Bảo hành</strong></td><td>12 tháng</td></tr> </tbody></table> <p><em>Lưu ý: Quý khách vui lòng đối chiếu mã OEM 97701-J9000 và đời xe Kona để đảm bảo chọn đúng phụ tùng tương thích.</em></p>
<!-- stage4-seo-specifications:start --><section class="product-seo-specifications"><h3>Thông số tra cứu</h3><table><tbody><tr><th scope="row">Tên sản phẩm</th><td>LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000</td></tr><tr><th scope="row">Mã sản phẩm</th><td>97701-J9000</td></tr><tr><th scope="row">Mã OEM</th><td>97701-J9000</td></tr><tr><th scope="row">Danh mục</th><td>Lốc Điều Hòa</td></tr><tr><th scope="row">Thương hiệu</th><td>DENSO</td></tr></tbody></table></section><!-- stage4-seo-specifications:end -->', 1, 0, 0, 0, 0, 'LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000 | 97701-J9000', 'Lốc điều hòa Kona Denso 97701-J9000 chính hãng Sản phẩm Lốc điều hòa Kona (mã 97701-J9000) của thương hiệu Denso là lựa chọn thay thế lý...', 'LỐC ĐIỀU HÒA điều hòa ô tô Kona 2018-2022 Denso 97701-J9000', '', 0, 0, NULL, 0, 1, 0, 'lốc điều hòa, lốc điều hòa điều hòa ô tô kona 2018-2022 denso 97701-j9000, lốc điều hòa , lốc điều hòa denso, thay lốc điều hòa chính hãng, kiểm tra lốc điều hòa');
INSERT INTO products ("id", "partner_id", "sku", "oem_code", "part_brand", "category_id", "name", "slug", "description", "short_specs", "price", "original_price", "stock", "reserved_stock", "weight_g", "width_cm", "height_cm", "depth_cm", "status", "reject_reason", "is_admin_created", "is_featured", "is_hot", "is_new", "sold_count", "view_count", "rating_avg", "rating_count", "warranty_months", "approved_by", "approved_at", "published_at", "created_at", "updated_at", "meta_title", "meta_description", "focus_keyword", "canonical_url", "og_image", "is_indexed", "price_before_tax", "tax_amount", "vat_rate", "oem_code2", "min_stock", "max_stock", "features", "specifications", "car_brand_id", "sale_price", "is_on_sale", "show_on_home", "show_on_promo", "seo_title", "seo_description", "seo_keyword", "video_url", "cost_price", "total_import_value", "location_code", "is_call_price", "is_active", "wholesale_price", "seo_secondary_keywords") VALUES (1274, 1, '97701-1Y000', '97701-1Y000 / 977011Y000', 'DENSO', 22, 'LỐC ĐIỀU HÒA điều hòa ô tô Morning | 97701-1Y000', 'loc-dieu-hoa-dieu-hoa-o-to-morning-97701-1y000', '<h2>Lốc điều hòa Morning 2010 — Chính Hãng Giá Tốt</h2> <p><strong>LỐC ĐIỀU HÒA điều hòa ô tô Morning 2010-2016 Denso 97701-1Y000</strong> (mã OEM: 97701-1Y000 / 977011Y000) là phụ tùng điện lạnh ô tô chính hãng thuộc hệ thống điều hòa xe Morning. Sản phẩm có chức năng chính là <strong>nén môi chất lạnh trong chu trình điều hòa</strong>, đảm bảo hệ thống làm mát hoạt động đúng công suất và hiệu quả.</p> <h3>Chức Năng & Nguyên Lý Hoạt Động</h3>
<p>Trong hệ thống điều hòa ô tô, lốc điều hòa đóng vai trò quan trọng trong chu trình làm lạnh. Lốc điều hòa được thiết kế tối ưu để đảm bảo khả năng nén môi chất lạnh trong chu trình điều hòa hiệu quả. Khi lốc điều hòa gặp sự cố, hệ thống làm lạnh sẽ giảm hiệu suất đáng kể hoặc ngừng hoạt động hoàn toàn, ảnh hưởng trực tiếp đến sự thoải mái của người lái và hành khách.</p> <h3>Dấu Hiệu Nhận Biết Cần Thay Lốc điều hòa</h3>
<ul> <li>Điều hòa không đủ lạnh hoặc không lạnh hoàn toàn</li> <li>Có tiếng ồn bất thường từ hệ thống điều hòa</li> <li>Rò rỉ môi chất hoặc nước bất thường</li> <li>Đèn báo lỗi điều hòa trên bảng điều khiển sáng lên</li>
</ul> <h3>Ưu Điểm Nổi Bật Khi Mua Tại CoolingSystems</h3>
<ul> <li><strong>Hàng chính hãng 100%:</strong> Mã 97701-1Y000 — nguồn gốc xuất xứ rõ ràng, đầy đủ giấy tờ kiểm định.</li> <li><strong>Tương thích hoàn hảo:</strong> Thiết kế chuẩn kích thước nguyên bản xe Morning, lắp đặt nhanh chóng không cần chỉnh sửa.</li> <li><strong>Độ bền vượt trội:</strong> Chất liệu cao cấp chịu nhiệt, chịu áp suất gas lớn và chống ăn mòn hiệu quả.</li> <li><strong>Tiết kiệm nhiên liệu:</strong> Hoạt động êm ái đúng công suất, giảm tải lốc điều hòa và động cơ xe.</li> <li><strong>Bảo hành 12 tháng:</strong> Đổi mới hoàn toàn nếu phát sinh lỗi từ nhà sản xuất.</li>
</ul> <h3>Hướng Dẫn Bảo Dưỡng Định Kỳ</h3>
<p>Để hệ thống điều hòa ô tô luôn hoạt động tốt và kéo dài tuổi thọ lốc điều hòa, Quý khách nên:</p>
<ul> <li>Kiểm tra và vệ sinh dàn lạnh, dàn nóng mỗi <strong>6 tháng</strong> hoặc <strong>10.000 km</strong>.</li> <li>Bổ sung gas điều hòa đúng định kỳ theo khuyến nghị nhà sản xuất.</li> <li>Thay thế phin lọc ga mỗi <strong>2 năm</strong> hoặc khi hệ thống có dấu hiệu bất thường.</li>
</ul> <div style="background:#f0f7ff;border:1px solid #070526;border-radius:10px;padding:16px;margin:20px 0;color:#1e293b;font-family:sans-serif"><p style="margin:0 0 8px;font-weight:700;color:#070526;font-size:16px">Cooling Systems - Chuỗi Dịch vụ & Phụ tùng Điều Hòa Ô Tô Chuyên Nghiệp.</p><ul style="margin:0;padding-left:20px;line-height:1.8;font-size:14px"><li><strong>Hotline & Zalo tư vấn:</strong> 0705 070 526</li><li><strong>Email hỗ trợ:</strong> hotrokhachhang@autopartsvietnam.com</li><li><strong>Website chính thức:</strong> <a href="https://coolingsystems.vn" target="_blank" style="color:#070526;font-weight:700">https://coolingsystems.vn</a></li></ul></div>', '<ul> <li><strong>Chính hãng DENSO:</strong> Đạt chuẩn OEM, nhập khẩu trực tiếp, đầy đủ chứng nhận chất lượng.</li> <li><strong>Mã 97701-1Y000:</strong> Khớp chính xác 100% với xe Morning 2010.</li> <li><strong>Chất liệu cao cấp:</strong> Chịu nhiệt độ cao, áp suất lớn, chống ăn mòn hiệu quả.</li> <li><strong>Lắp đặt nhanh chóng:</strong> Chuẩn kích thước nguyên bản, không cần chỉnh sửa hay đục khoét.</li> <li><strong>Tiết kiệm nhiên liệu:</strong> Hoạt động hiệu quả, giảm tải lốc điều hòa và động cơ.</li> <li><strong>Bảo hành 12 tháng:</strong> Cam kết đổi mới nếu phát sinh lỗi từ nhà sản xuất.</li>
</ul>', 7500000, 7527000, 999, 0, 6000, 20, 15, 15, 'published', '', 0, 0, 0, 0, 0, 4, 0.0, 0, 12, NULL, NULL, NULL, '2026-05-30 23:31:44', '2026-08-12 16:28:40', 'LỐC ĐIỀU HÒA điều hòa ô tô cho Kia Morning chính hãng | CoolingSyste', 'Lốc điều hòa Morning 2010 — Chính Hãng Giá Tốt LỐC ĐIỀU HÒA điều hòa ô tô Morning 2010-2016 Denso 97701-1Y000 (mã OEM: 97701-1Y000 / 977011Y000) là phụ...', 'lc điu ha điều hòa', '', '/uploads/products/dan-nong-dieu-hoa-o-to-cho-kia-morning-2010-2016-magneti-marelli-97606-1y000-mm-976061y000-20260731093722-076be61d.webp', 1, 6818182, 681818, 10, '977011Y000', 5, 999, '<ul> <li><strong>Mã OEM 97701-1Y000 / 977011Y000 </strong> — Khớp chính xác 100% theo tiêu chuẩn nhà sản xuất DENSO.</li> <li><strong>Chính hãng DENSO</strong> — Đạt tiêu chuẩn kiểm định nghiêm ngặt, nhập khẩu trực tiếp.</li> <li><strong>Tương thích hoàn hảo</strong> — Lắp đặt vừa vặn 100% nguyên bản xe , không cần chỉnh sửa.</li> <li><strong>Chất liệu cao cấp</strong> — Vật liệu chịu nhiệt độ cao, áp suất lớn, chống ăn mòn hiệu quả.</li> <li><strong>Hiệu suất ổn định</strong> — Lốc điều hòa (Compressor) hoạt động êm ái, duy trì làm lạnh đúng công suất.</li> <li><strong>Bảo hành 12 tháng</strong> — Cam kết đổi mới nếu phát sinh lỗi từ nhà sản xuất.</li>
