INSERT INTO products ("id", "partner_id", "sku", "oem_code", "part_brand", "category_id", "name", "slug", "description", "short_specs", "price", "original_price", "stock", "reserved_stock", "weight_g", "width_cm", "height_cm", "depth_cm", "status", "reject_reason", "is_admin_created", "is_featured", "is_hot", "is_new", "sold_count", "view_count", "rating_avg", "rating_count", "warranty_months", "approved_by", "approved_at", "published_at", "created_at", "updated_at", "meta_title", "meta_description", "focus_keyword", "canonical_url", "og_image", "is_indexed", "price_before_tax", "tax_amount", "vat_rate", "oem_code2", "min_stock", "max_stock", "features", "specifications", "car_brand_id", "sale_price", "is_on_sale", "show_on_home", "show_on_promo", "seo_title", "seo_description", "seo_keyword", "video_url", "cost_price", "total_import_value", "location_code", "is_call_price", "is_active", "wholesale_price", "seo_secondary_keywords") VALUES (1470, 1, 'DS07-2403', 'DS07-2403 / DS072403', 'DENSO', 24, 'PULLEY điều hòa ô tô Matiz 2009-2013 Denso DS07-2403 | DS07-2403', 'pulley-dieu-hoa-o-to-matiz-2009-2013-denso-ds07-2403-ds07-2403', 'Pulley Matiz Denso DS07-2403 chính hãng Pulley Matiz mã Denso DS07-2403 là phụ tùng điều hòa ô tô chính hãng, được thiết kế chuyên dụng Matiz (2009-2013). Đây là bộ phận đảm nhiệm vai trò quan trọng trong hệ thống điều hòa, giúp xe vận hành mát mẻ và ổn định. Sản phẩm do Denso – tập đoàn linh kiện ô tô hàng đầu Nhật Bản – sản xuất theo tiêu chuẩn OEM, đảm bảo chất lượng tương đương linh kiện nguyên bản theo xe. Vì sao nên chọn Pulley Matiz chính hãng Denso? Denso là nhà cung cấp linh kiện gốc (OEM) hầu hết các hãng xe lớn trên thế giới. Khi chọn pulley matiz mã DS07-2403, bạn nhận được sản phẩm đạt chuẩn chính xác từng chi tiết, lắp vừa khít mà không cần chỉnh sửa, đồng thời được kiểm định nghiêm ngặt về độ bền và hiệu suất. Hiệu suất làm mát cao: duy trì nhiệt độ cabin ổn định, mát sâu kể cả khi trời nắng gắt. Vận hành êm ái: giảm thiểu độ rung và tiếng ồn trong quá trình hoạt động. Độ bền vượt trội: chịu được áp suất và nhiệt độ cao, tuổi thọ dài lâu. Tiết kiệm nhiên liệu: thiết kế tối ưu giúp giảm tải động cơ. Lắp đặt chính xác: tương thích hoàn hảo với hệ thống nguyên bản của Matiz. Lưu ý khi lắp đặt và sử dụng Để đảm bảo lắp đặt chính xác, quý khách nên đối chiếu mã OEM DS07-2403 với phụ tùng đang sử dụng trên xe, đồng thời kiểm tra đời xe và thông số kỹ thuật. Việc lắp đặt nên được thực hiện bởi kỹ thuật viên có chuyên môn, kết hợp nạp đúng loại và lượng môi chất lạnh để hệ thống vận hành tối ưu.
<!-- stage4-seo-description:start --><section class="product-seo-details"><h2>Thông tin pulley điều hòa ô</h2><p><strong>pulley điều hòa ô</strong> được nhận diện theo tên sản phẩm và mã tham chiếu đang lưu trên hệ thống. Khách hàng có thể sử dụng tên hoặc mã sản phẩm để tra cứu và đối chiếu trước khi đặt hàng.</p><h3>Thông tin nhận diện sản phẩm</h3><ul><li><strong>Tên sản phẩm:</strong> PULLEY điều hòa ô tô Matiz 2009-2013 Denso DS07-2403</li><li><strong>Mã sản phẩm:</strong> DS07-2403</li><li><strong>Mã OEM:</strong> DS07-2403</li><li><strong>Danh mục:</strong> Van Đuôi Lốc</li><li><strong>Thương hiệu:</strong> DENSO</li></ul><figure><img src="/uploads/products/p_6a1e3a8306f82.jpg" alt="PULLEY điều hòa ô tô Matiz 2009-2013 Denso DS07-2403 - DS07-2403" loading="lazy"><figcaption>PULLEY điều hòa ô tô Matiz 2009-2013 Denso DS07-2403</figcaption></figure></section><!-- stage4-seo-description:end --> <div style="background:#f0fdf4;border:1.5px solid #22c55e;border-radius:10px;padding:16px;margin:20px 0;"> <strong style="color:#15803d;font-size:15px;display:block;margin-bottom:8px;">Cooling Systems- Chuỗi Dịch vụ & Phụ tùng Điều Hòa Ô Tô Chuyên Nghiệp.</strong> <ul style="margin:0 0 0 18px;color:#166534;font-size:13.5px;line-height:1.6;padding:0;"> <li>• Hotline & Zalo tư vấn: 0705.0705.26</li> <li>• Email hỗ trợ: hotrokhachhang@autopartsvietnam.com</li> <li>• Website chính thức: https://coolingsystems.vn</li> </ul>
</div>', '', 230000, 261000, 999, 0, 400, 30, 10, 5, 'draft', '', 0, 0, 0, 0, 0, 2, 0.0, 0, 12, NULL, NULL, NULL, '2026-05-31 17:49:00', '2026-08-12 16:28:40', '', 'Pulley Matiz Denso DS07-2403 chính hãng Pulley Matiz mã Denso DS07-2403 là phụ tùng điều hòa ô tô chính hãng, được thiết kế chuyên dụng ...', 'PULLEY điều hòa ô tô Matiz 2009-2013 Denso DS07-2403', '', 'p_6a1e3a8306f82.jpg', 0, 209091, 20909, 10, 'DS072403', 5, 999, '<h3>Đặc điểm nổi bật của Pulley Matiz</h3> <p>Pulley Matiz Denso mã DS07-2403 sở hữu nhiều đặc điểm nổi bật, đáp ứng tốt yêu cầu khắt khe của hệ thống điều hòa trên Matiz:</p> <ul> <li><strong>Xuất xứ chính hãng Denso:</strong> linh kiện OEM đạt chuẩn, đúng mã DS07-2403.</li> <li><strong>Khả năng làm mát mạnh mẽ:</strong> hiệu suất cao, làm lạnh nhanh và sâu.</li> <li><strong>Vận hành êm, ít rung:</strong> mang lại sự thoải mái khi sử dụng.</li> <li><strong>Vật liệu bền bỉ:</strong> chịu nhiệt và áp suất tốt, chống ăn mòn.</li> <li><strong>Tiết kiệm nhiên liệu:</strong> thiết kế tối ưu giảm tải động cơ.</li> <li><strong>Tương thích chính xác:</strong> lắp vừa khít với Matiz.</li> </ul>
<!-- stage4-seo-features:start --><section class="product-seo-features"><h3>Đặc điểm nhận diện</h3><ul><li><strong>Sản phẩm:</strong> PULLEY điều hòa ô tô Matiz 2009-2013 Denso DS07-2403</li><li><strong>Mã tham chiếu:</strong> DS07-2403</li><li><strong>Thông tin tra cứu:</strong> pulley điều hòa ô</li></ul></section><!-- stage4-seo-features:end -->', '<h3>Thông số kỹ thuật Pulley Matiz Denso DS07-2403</h3> <table border="1" style="border-collapse:collapse;width:100%"><tbody> <tr><td style="width:40%"><strong>Tên sản phẩm</strong></td><td>Pulley Matiz</td></tr> <tr><td><strong>Mã sản phẩm (SKU)</strong></td><td>DS07-2403</td></tr> <tr><td><strong>Mã OEM</strong></td><td>DS07-2403 / DS072403</td></tr> <tr><td><strong>Thương hiệu</strong></td><td>Denso (Nhật Bản)</td></tr> <tr><td><strong>Hãng xe tương thích</strong></td><td> Matiz</td></tr> <tr><td><strong>Đời xe</strong></td><td>2009-2013</td></tr> <tr><td><strong>Loại phụ tùng</strong></td><td>Pulley</td></tr> <tr><td><strong>Điện áp hoạt động</strong></td><td>12V</td></tr> <tr><td><strong>Môi chất lạnh tương thích</strong></td><td>R134a / R1234yf</td></tr> <tr><td><strong>Chất liệu</strong></td><td>Hợp kim nhôm & linh kiện cao cấp, chống ăn mòn</td></tr> <tr><td><strong>Tiêu chuẩn</strong></td><td>OEM – chính hãng</td></tr> <tr><td><strong>Tình trạng</strong></td><td>Mới 100%</td></tr> <tr><td><strong>Bảo hành</strong></td><td>12 tháng</td></tr> </tbody></table> <p><em>Lưu ý: Quý khách vui lòng đối chiếu mã OEM DS07-2403 và đời xe Matiz để đảm bảo chọn đúng phụ tùng tương thích.</em></p>
