INSERT INTO products ("id", "partner_id", "sku", "oem_code", "part_brand", "category_id", "name", "slug", "description", "short_specs", "price", "original_price", "stock", "reserved_stock", "weight_g", "width_cm", "height_cm", "depth_cm", "status", "reject_reason", "is_admin_created", "is_featured", "is_hot", "is_new", "sold_count", "view_count", "rating_avg", "rating_count", "warranty_months", "approved_by", "approved_at", "published_at", "created_at", "updated_at", "meta_title", "meta_description", "focus_keyword", "canonical_url", "og_image", "is_indexed", "price_before_tax", "tax_amount", "vat_rate", "oem_code2", "min_stock", "max_stock", "features", "specifications", "car_brand_id", "sale_price", "is_on_sale", "show_on_home", "show_on_promo", "seo_title", "seo_description", "seo_keyword", "video_url", "cost_price", "total_import_value", "location_code", "is_call_price", "is_active", "wholesale_price", "seo_secondary_keywords") VALUES (1523, 1, '80311-T0N-T01', '80311-T0N-T01 / 80311T0NT01', 'DENSO', 41, 'ỐNG DẪN GAS điều hòa ô tô CR-V 2013-2017 Denso 80311-T0N-T01 | 80311-T0N-T01', 'ong-dan-gas-dieu-hoa-o-to-cr-v-2013-2017-denso-80311-t0n-t01-80311-t0n-t01', 'Ống dẫn gas CR-V Denso 80311-T0N-T01 chính hãng Bạn đang tìm Ống dẫn gas CR-V chính hãng CR-V (2013-2017)? Sản phẩm mã Denso 80311-T0N-T01 là giải pháp tối ưu – đảm nhiệm vai trò quan trọng trong hệ thống điều hòa, giúp xe vận hành mát mẻ và ổn định. Được sản xuất trên dây chuyền đạt chuẩn của Denso Nhật Bản, sản phẩm đảm bảo độ chính xác cao khi lắp đặt và hiệu suất làm mát vượt trội. Điểm khác biệt của Ống dẫn gas CR-V Denso Sản phẩm Denso mã 80311-T0N-T01 nổi bật nhờ chất lượng đồng đều và tuổi thọ cao. Với ống dẫn gas cr-v, người dùng CR-V hoàn toàn yên tâm về khả năng tương thích, độ kín khít và hiệu quả làm lạnh trong điều kiện khí hậu nóng ẩm tại Việt Nam. Thương hiệu uy tín: Denso – nhà sản xuất điều hòa ô tô hàng đầu thế giới. Hiệu năng tối ưu: làm mát hiệu quả, duy trì sự thoải mái trong cabin. Vật liệu cao cấp: chịu nhiệt, chịu áp và bền theo thời gian. Tiết kiệm điện năng & nhiên liệu: vận hành mượt, giảm hao tổn công suất. Tương thích chuẩn xác: thiết kế riêng CR-V. Tư vấn lắp đặt & bảo dưỡng Sản phẩm tương thích với CR-V (2013-2017). Để vận hành bền bỉ, khuyến nghị bảo dưỡng hệ thống điều hòa định kỳ, kiểm tra áp suất ga và vệ sinh dàn nhiệt thường xuyên. Nên lắp đặt tại gara uy tín để đảm bảo độ kín khít và an toàn ống dẫn gas cr-v.
<!-- stage4-seo-description:start --><section class="product-seo-details"><h2>Thông tin ống dẫn gas điều</h2><p><strong>ống dẫn gas điều</strong> được nhận diện theo tên sản phẩm và mã tham chiếu đang lưu trên hệ thống. Khách hàng có thể sử dụng tên hoặc mã sản phẩm để tra cứu và đối chiếu trước khi đặt hàng.</p><h3>Thông tin nhận diện sản phẩm</h3><ul><li><strong>Tên sản phẩm:</strong> ỐNG DẪN GAS điều hòa ô tô CR-V 2013-2017 Denso 80311-T0N-T01</li><li><strong>Mã sản phẩm:</strong> 80311-T0N-T01</li><li><strong>Mã OEM:</strong> 80311-T0N-T01</li><li><strong>Danh mục:</strong> Vật Tư & Phụ Kiện Khác</li><li><strong>Thương hiệu:</strong> DENSO</li></ul><figure><img src="/uploads/products/p_6a1e3abb8870c.jpg" alt="ỐNG DẪN GAS điều hòa ô tô CR-V 2013-2017 Denso 80311-T0N-T01 - 80311-T0N-T01" loading="lazy"><figcaption>ỐNG DẪN GAS điều hòa ô tô CR-V 2013-2017 Denso 80311-T0N-T01</figcaption></figure></section><!-- stage4-seo-description:end --> <div style="background:#f0fdf4;border:1.5px solid #22c55e;border-radius:10px;padding:16px;margin:20px 0;"> <strong style="color:#15803d;font-size:15px;display:block;margin-bottom:8px;">Cooling Systems- Chuỗi Dịch vụ & Phụ tùng Điều Hòa Ô Tô Chuyên Nghiệp.</strong> <ul style="margin:0 0 0 18px;color:#166534;font-size:13.5px;line-height:1.6;padding:0;"> <li>• Hotline & Zalo tư vấn: 0705.0705.26</li> <li>• Email hỗ trợ: hotrokhachhang@autopartsvietnam.com</li> <li>• Website chính thức: https://coolingsystems.vn</li> </ul>
</div>', '', 420000, 458000, 999, 0, 400, 30, 10, 5, 'draft', '', 0, 0, 0, 0, 0, 1, 0.0, 0, 12, NULL, NULL, NULL, '2026-05-31 17:49:01', '2026-08-12 16:28:40', '', 'Ống dẫn gas CR-V Denso 80311-T0N-T01 chính hãng Bạn đang tìm Ống dẫn gas CR-V chính hãng CR-V (2013-2017)? Sản phẩm mã Denso...', 'ỐNG DẪN GAS điều hòa ô tô CR-V 2013-2017 Denso 80311-T0N-T01', '', 'p_6a1e3abb8870c.jpg', 0, 381818, 38182, 10, '80311T0NT01', 5, 999, '<h3>Đặc điểm nổi bật của Ống dẫn gas CR-V</h3> <p>Ống dẫn gas CR-V chính hãng Denso 80311-T0N-T01 được đánh giá cao nhờ các đặc điểm sau:</p> <ul> <li><strong>Thương hiệu Denso uy tín:</strong> nhà cung cấp điều hòa ô tô toàn cầu.</li> <li><strong>Làm lạnh sâu, hiệu quả:</strong> đáp ứng tốt mọi điều kiện thời tiết.</li> <li><strong>Hoạt động êm ái:</strong> không gây tiếng ồn khó chịu trong cabin.</li> <li><strong>Bền bỉ vượt trội:</strong> vật liệu cao cấp, chịu lực tốt.</li> <li><strong>Tiết kiệm & thân thiện:</strong> tối ưu vận hành, giảm tiêu hao.</li> <li><strong>Lắp đặt chuẩn xác:</strong> khớp hoàn hảo với CR-V.</li> </ul>
